    <div class="my-match-section"><h2>Partidos en los que participás</h2><?php if ($joined === []): ?><div class="profile-card"><p class="booking-muted">Todavía no participás en partidos.</p></div><?php else: ?><div class="match-list"><?php foreach ($joined as $match): ?><a class="match-list-item profile-card" href="<?= base_url('app/partidos/detalle/' . $match['id']) ?>"><span class="booking-service"><?= esc($match['service_name']) ?></span><strong><?= esc($match['field_name']) ?></strong><span><?= esc(date('d/m/Y', strtotime($match['date']))) ?> · <?= esc(substr($match['time_from'], 0, 5)) ?></span></a><?php endforeach; ?></div><?php endif; ?></div>
